INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(50711, 'Ezekiel 31:8', 'Ezekiel', 31, 8, 'د خدای د باغ د سبر یوه ونه هم پرتله کېدای نه شوه هغې سره د سروې یوې ونې نه لرلې داسې څانګې او نه لرلې د چنار ونې داسې څانګې داسې ښکلې نه وه د خدای د باغ هم یوه ونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_8.mp3', '', 1761754199, 1761754199),
(50712, 'Ezekiel 31:9', 'Ezekiel', 31, 9, 'ما ښایسته کړې وه هغه په زیاتو څانګو باندې بخیلي کوله په باغ عدن کې د خدای ټولو ونو د هغې سره›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_9.mp3', '', 1761754199, 1761754199),
(50713, 'Ezekiel 31:10', 'Ezekiel', 31, 10, 'نو زه څښتن تعالی د مصر پاچا ته داسې وایم: ‹په دې خاطر چېهغه ونه دومره لوړه شوه چې ورېځو ته رسېدله، نو د خپل لوړوالي له امله مغروره شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_10.mp3', '', 1761754199, 1761754199),
(50714, 'Ezekiel 31:11', 'Ezekiel', 31, 11, 'نو ځکه هغه مې لاندې وغورځوله او هغه مې د نورو قومونو یو واکمن ته تسلیم کړه او هغه ورسره د هغې د بدکارۍ له مخې سخت چلند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_11.mp3', '', 1761754199, 1761754199),
(50715, 'Ezekiel 31:12', 'Ezekiel', 31, 12, 'بې‌رحمه پرديو خلکو هغه ونه ووهله او هغه یې پرېښودله. د هغې ماتې شوې څانګې د دې وطن په هر غره او هرې درې کې پرتې وې. کوم قومونه چې د هغې د سیوري لاندې اوسېدل، نو هغوی هغه پرېښودله او لاړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_12.mp3', '', 1761754199, 1761754199),
(50716, 'Ezekiel 31:13', 'Ezekiel', 31, 13, 'ټول مرغان د دې لوېدلې ونې په تنه باندې کښېناستل او ټول وحشي حیوانات د هغې په څانګو باندې ګرځېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_13.mp3', '', 1761754199, 1761754199),
(50717, 'Ezekiel 31:14', 'Ezekiel', 31, 14, 'نو له دې وروسته به هېڅ یوه ونه چې زیاتې اوبه هم ولري، هغه به هېڅکله د دې ونې په شان دومره لوړه نه شي چې ورېځو ته ورسیږي. ځکه هغوی ټول زما د رضا سره سم فنا‌کېدونکي دي او لکه د فاني انسانانو په شان به مري او د مړو دنیا ته به ورځي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_14.mp3', '', 1761754199, 1761754199),
(50718, 'Ezekiel 31:15', 'Ezekiel', 31, 15, 'څښتن تعالی داسې وایي: ‹په کومه ورځ چې هغه ونه د مړو دنیا ته لاړه، نو ما د ځمکې لاندې اوبه پټې کړې چې ټوله نړۍ ویر وکړي. په دې خاطر چې هغه ونه مړه شوې ده، نو ما سیندونه ودرول او ما پرېنښودل چې د هغو ډېرې ویالې ورڅخه روانې شي. ما د لبنان په غرونو باندې تیاره راوستله او د ځنګل ټولې ونې مې وچې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_15.mp3', '', 1761754199, 1761754199),
(50719, 'Ezekiel 31:16', 'Ezekiel', 31, 16, 'کله چې ما هغه لاندې د مړو دنیا ته وروغورځوله، نو ما د هغې د لوېدلو په اواز قومونه له وېرې ولړزول. د عدن ټولې ونې او د لبنان ډېرې ښې ونې چې په اوبو باندې مړې شوې وې او لاندې د مړو دنیا ته تللې وې، هغوی د دې ونې په لوېدلو باندې تسلي وموندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_16.mp3', '', 1761754199, 1761754199),
(50720, 'Ezekiel 31:17', 'Ezekiel', 31, 17, 'د سبر د ونې ملاتړ کوونکي چې د قومونو په منځ کې د هغې د سیوري لاندې اوسېدلي وو، هغوی هم ورسره د مړو دنیا ته لاړل. هغوی د هغو خلکو سره چې په جنګ کې وژل شوي وو، یوځای شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_17.mp3', '', 1761754199, 1761754199),
(50721, 'Ezekiel 31:18', 'Ezekiel', 31, 18, 'ای فرعونه او ټولو خلکو، تاسو د هغې ونې په شان یئ. د عدن د باغ هېڅ یوه ونه نه شي کولای په عزت او لویۍ کې ستا سره سیالي وکړي. خو اوس به ته د عدن د ونو په شان د مړو دنیا ته وغورځول شې او د بې دینه او هغو خلکو سره به یو ځای کېږې چې په جنګ کې وژل شوي دي. ما څښتن تعالی داسې ویلي دي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel31_verse_18.mp3', '', 1761754199, 1761754199),
(50722, 'Deuteronomy 6:1', 'Deuteronomy', 6, 1, 'څښتن ماته وویل چې تاسو ته دغه ټول قوانین درکوم، ترڅو وکولای شئ په هغې خاورې کې د هغو اطاعت وکړئ چې هغه یې درکوي. تاسو به زر د اردن د سیند څخه تېر شئ او هغه خاوره به ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_1.mp3', '', 1761754199, 1761754199),
(50723, 'Deuteronomy 6:2', 'Deuteronomy', 6, 2, 'ترڅو پورې چې تاسو ژوندي یئ، تاسو او ستاسو اولاده باید د خپل څښتن خدای عزت وکړئ او د هغه د ټولو قوانینو اطاعت وکړئ چې زه یې درکوم، ترڅو تاسو په هغه خاوره کې زیات عمر ولرئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_2.mp3', '', 1761754199, 1761754199),
(50724, 'Deuteronomy 6:3', 'Deuteronomy', 6, 3, 'ای د اسراییلو خلکو، غوږ ونیسئ او په غور سره هغو قوانینو ته غاړه کېږدئ! بیا به ستاسو هر کار سم شي او ستاسو څخه به یو لوی قوم جوړ شي او زمونږ د نیکونو د څښتن خدای د وعدې سره سم به په هغې خاوره کې واوسېږئ چې غني او حاصلخېزه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_3.mp3', '', 1761754199, 1761754199),
(50725, 'Deuteronomy 6:4', 'Deuteronomy', 6, 4, 'ای د اسراییلو خلکو، واورئ! یوازېنی خدای چې شتون لري هغه زمونږ څښتن خدای دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_4.mp3', '', 1761754199, 1761754199),
(50726, 'Deuteronomy 6:5', 'Deuteronomy', 6, 5, 'د زړه له کومي په خپل ټول ځان او قوت سره د خپل څښتن خدای سره مینه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_5.mp3', '', 1761754199, 1761754199),
(50727, 'Deuteronomy 6:6', 'Deuteronomy', 6, 6, 'دا قوانین چې زه یې نن تاسو ته درکوم، هغه هېڅکله مه هېروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_6.mp3', '', 1761754199, 1761754199),
(50728, 'Deuteronomy 6:7', 'Deuteronomy', 6, 7, 'هغه خپلو اولادونو ته ورزده کړئ. که په کور کې یئ یا په لاره روان یئ یا ارام کوئ یا کار کوئ، نو په دې هکله د هغوی سره خبرې کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_7.mp3', '', 1761754199, 1761754199),
(50729, 'Deuteronomy 6:8', 'Deuteronomy', 6, 8, 'هغه ولیکئ او په خپلو مټو او تندیو باندې یې وتړئ چې د هغو په اطاعت کولو کې درسره مرسته وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_8.mp3', '', 1761754199, 1761754199),
(50730, 'Deuteronomy 6:9', 'Deuteronomy', 6, 9, 'دا قوانین د خپلو کورونو د دروازو په چوکاټونو او د خپلو ښارونو په دروازو باندې ولیکئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_9.mp3', '', 1761754199, 1761754199),
(50731, 'Deuteronomy 6:10', 'Deuteronomy', 6, 10, 'څښتن خدای ستاسو د نیکونو یعنې ابراهیم، اسحاق او یعقوب سره وعده کړې وه چې هغه به تاسو ته دا ځمکه درکړي. اوس به هغه تاسو هلته ورولي او تاسو ته به لوی لوی ښارونه چې داسې ښې ودانۍ په کې وي چې تاسو خپله نه دي جوړې کړې، درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_10.mp3', '', 1761754199, 1761754199),
(50732, 'Deuteronomy 6:11', 'Deuteronomy', 6, 11, 'کورونه به د ښو ښو شیانو څخه ډک وي چې تاسو په کې نه وي ایښي او څاه ګانې به وي چې تاسو به نه وي کیندلي او د انګورو او د زیتونو باغونه به وي چې تاسو به نه وي کرلي. کله چې څښتن تاسو دې ځمکې ته ورولي او تاسو ته د خوراک دپاره هرڅه درورسیږي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_11.mp3', '', 1761754199, 1761754199),
(50733, 'Deuteronomy 6:12', 'Deuteronomy', 6, 12, 'نو پام کوئ چې څښتن هېر نه کړئ چې تاسو یې د مصر څخه چې په کې غلامان وئ، راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_12.mp3', '', 1761754199, 1761754199),
(50734, 'Deuteronomy 6:13', 'Deuteronomy', 6, 13, 'د خپل څښتن خدای څخه ووېرېږئ. یوازې د هغه عبادت کوئ او یوازې د هغه په نوم قسم خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_13.mp3', '', 1761754199, 1761754199),
(50735, 'Deuteronomy 6:14', 'Deuteronomy', 6, 14, 'نورو خدایانو یعنې د هغو قومونو خدایانو ته عبادت مه کوئ چې ستاسو په شاوخوا کې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_14.mp3', '', 1761754199, 1761754199),
(50736, 'Deuteronomy 6:15', 'Deuteronomy', 6, 15, 'که چېرې تاسو د نورو خدایانو عبادت وکړئ، د څښتن قهر به د اور په شان درباندې نازل شي او تاسو به د ځمکې د مخ څخه ورک کړي، ځکه ستاسو څښتن خدای چې ستاسو په منځ کې حاضر دی، هغه غیرتي خدای دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_15.mp3', '', 1761754199, 1761754199),
(50737, 'Deuteronomy 6:16', 'Deuteronomy', 6, 16, 'خپل څښتن خدای مه ازمایئ، لکه څنګه چې تاسو په مسا کې وازمایلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_16.mp3', '', 1761754199, 1761754199),
(50738, 'Deuteronomy 6:17', 'Deuteronomy', 6, 17, 'تل په غور سره د هغو ټولو قوانینو اطاعت کوئ چې تاسو ته یې درکړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_17.mp3', '', 1761754199, 1761754199),
(50739, 'Deuteronomy 6:20', 'Deuteronomy', 6, 20, 'په راتلونکې کې به ستاسو اولادونه پوښتنه وکړي چې زمونږ څښتن خدای ولې په مونږ باندې امر کړی دی چې دغو ټولو قوانینو ته غاړه کېږدو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_20.mp3', '', 1761754199, 1761754199),
(50740, 'Deuteronomy 6:21', 'Deuteronomy', 6, 21, 'بیا هغوی ته ووایئ: ‹مونږ په مصر کې د فرعون غلامان وو او څښتن په خپل قوي مټ سره ازاد کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_21.mp3', '', 1761754199, 1761754199),
(50741, 'Deuteronomy 6:22', 'Deuteronomy', 6, 22, 'مونږ په خپلو سترګو ولیدل چې معجزې یې وکړې او په مصریانو او فرعون او د هغه په ټولو درباریانو باندې یې وېروونکي کارونه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_22.mp3', '', 1761754199, 1761754199),
(50742, 'Deuteronomy 6:23', 'Deuteronomy', 6, 23, 'هغه مونږ د مصر څخه ازاد کړو چې دلته مو راولي او دا ځمکه راکړي لکه څنګه چې هغه زمونږ د نیکونو سره وعده کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_23.mp3', '', 1761754199, 1761754199),
(50743, 'Deuteronomy 6:24', 'Deuteronomy', 6, 24, 'بیا زمونږ څښتن خدای په مونږ باندې امر وکړ چې دغو ټولو قوانینو ته غاړه کېږدو او د هغه څخه ووېرېږو. که چېرې مونږ داسې وکړو، نو هغه به تل زمونږ په قوم باندې پام کوي او هغه به نېکمرغه وساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_24.mp3', '', 1761754199, 1761754199),
(50744, 'Deuteronomy 6:25', 'Deuteronomy', 6, 25, 'که چېرې مونږ په وفادارۍ سره د خدای هر امر ته غاړه کېږدو، هغه به زمونږ څخه خوشحاله شي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy6_verse_25.mp3', '', 1761754199, 1761754199),
(50745, 'Malachi 2:1', 'Malachi', 2, 1, '”ګورئ اوس دا حکم ستاسو دپاره دے، اے اِمامانو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_1.mp3', '', 1761754199, 1761754199),
(50746, 'Malachi 2:2', 'Malachi', 2, 2, 'کۀ تاسو غوږ نۀ نيسئ، او کۀ تاسو د خپل زړۀ نه زما د نوم احترام نۀ کوئ،“ مالِک خُدائ ربُ الافواج فرمائى، ”زۀ به په تاسو لعنت نازل کړم، او زۀ به ستاسو نعمتونه لعنتى کړم. په اصل کښې ما هغوئ د اول نه لعنتى کړى دى، ځکه چې تاسو د خپل زړۀ نه زما احترام ونۀ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_2.mp3', '', 1761754199, 1761754199),
(50747, 'Malachi 2:3', 'Malachi', 2, 3, 'ستاسو په وجه به زۀ ستاسو اولاد ورټم، زۀ به ستاسو په مخونو ستاسو د اختر د قربانو ګند واچوم، او تاسو به دې سره بهر وغورزولے شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_3.mp3', '', 1761754199, 1761754199),
(50748, 'Malachi 2:4', 'Malachi', 2, 4, 'او تاسو به پوهه شئ چې ما تاسو ته دا حکم درلېږلے دے چې زما لوظ به د ليويانو سره جارى وى،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_4.mp3', '', 1761754199, 1761754199),
(50749, 'Malachi 2:5', 'Malachi', 2, 5, '”زما لوظ هغوئ سره وو، د ژوند او امن لوظ، او ما دا هغوئ ته ورکړو چې زما تعظيم وکړى، او هغوئ زما عزت وکړو او زما د نوم د دهشت نه ويرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_5.mp3', '', 1761754199, 1761754199),
(50750, 'Malachi 2:6', 'Malachi', 2, 6, 'رښتينے شريعت د هغوئ په خولۀ کښې وو او هيڅ دروغ د هغوئ په شونډو نۀ وو. هغوئ ما سره په امن او صداقت روان وُو، او ډېر يې د ګناه نه واړول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_6.mp3', '', 1761754199, 1761754199),
(50751, 'Malachi 2:7', 'Malachi', 2, 7, 'د اِمام د خولې دا فرض دى چې صحيح تعليم خور کړى، او د هغۀ د خولې نه دې خلق د شريعت لټون وکړى، ځکه چې هغه د مالِک خُدائ ربُ الافواج پېغام رسوونکے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_7.mp3', '', 1761754199, 1761754199),
(50752, 'Malachi 2:8', 'Malachi', 2, 8, 'خو تاسو اِمامان د خپلې صحيح لارې نه واوړېدئ او ستاسو د شريعت په وجه ډېرو تيندک خوړلے دے. د ليويانو سره زما شوے لوظ تا مات کړو،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_8.mp3', '', 1761754199, 1761754199),
(50753, 'Malachi 2:9', 'Malachi', 2, 9, '”نو په دې وجه ما تۀ د ټولو خلقو په وړاندې سپک او عاجز کړې، ځکه چې تا زما په طريقو عمل ونۀ کړو خو د شريعت په مسئلو کښې دې طرفدارى وکړه.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_9.mp3', '', 1761754199, 1761754199),
(50754, 'Malachi 2:10', 'Malachi', 2, 10, 'آيا زمونږ ټولو پلار يو نۀ دے؟ آيا يو خُدائ پاک مونږ جوړ کړى نۀ يُو؟ مونږ بيا ولې په خپلو کښې د يو بل سره په بې‌وفائى کولو د خپل پلار نيکۀ د لوظ بې‌احترامى کوُو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_10.mp3', '', 1761754199, 1761754199),
(50755, 'Malachi 2:11', 'Malachi', 2, 11, 'يهوداه بې‌ايمانى وکړه. يو حرام عمل يې په اِسرائيل يعنې يروشلم کښې کړے وو، د هغه پاک کور چې مالِک خُدائ ورسره مينه کوله د هغه ښځو سره په وادۀ کولو چې بُت پرسته وې، يهوداه بې‌احترامى وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_11.mp3', '', 1761754199, 1761754199),
(50756, 'Malachi 2:12', 'Malachi', 2, 12, 'د هغه سړى دپاره چې څوک داسې کوى، چې هغه څوک هم وى، مالِک خُدائ دې هغه د بنى اِسرائيلو د قوم نه وشړى. کۀ هغه مالِک خُدائ ربُ الافواج ته نذرانې هم راوړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_12.mp3', '', 1761754199, 1761754199),
(50757, 'Malachi 2:13', 'Malachi', 2, 13, 'يو بل کار تاسو وکړئ، تاسو د مالِک خُدائ قربان‌ګاه په اوښکو ډکه کړئ. تاسو وژاړئ او زارى وکړئ ځکه چې نور هغه نۀ ستاسو نذرانو ته ګورى او نۀ يې ستاسو د لاسونو نۀ په خوشحالۍ سره قبلوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_13.mp3', '', 1761754199, 1761754199),
(50758, 'Malachi 2:14', 'Malachi', 2, 14, 'تاسو تپوس کوئ چې، ”ولې؟“ دا ځکه چې مالِک خُدائ ستا او ستا د ځوانۍ د ښځې په مينځ کښې ګواه دے، ځکه چې تا د هغې سره ټګى وکړه، اګر کۀ هغه ستا په ژوند کښې شريکه ده، او تا هغې سره نِکاح کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_14.mp3', '', 1761754199, 1761754199),
(50759, 'Malachi 2:15', 'Malachi', 2, 15, 'آيا مالِک خُدائ تاسو دواړه يو نۀ کړئ؟ تاسو په زړۀ او ځان د هغۀ يئ. او خُدائ د دې نه څۀ غواړى؟ ځکه چې هغه نېک اولاد غواړى. نو د خپل زړۀ خيال ساته، او خپلې د ځوانۍ د ښځې سره ټګى مۀ کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_15.mp3', '', 1761754199, 1761754199),
(50760, 'Malachi 2:16', 'Malachi', 2, 16, '”زۀ طلاق نه نفرت کوم،“ د بنى اِسرائيلو مالِک خُدائ فرمائى، ”او زۀ د هغه سړى نه نفرت کوم چا چې د ظلم جامې اغوستې وى،“ مالِک خُدائ ربُ الافواج فرمائى. ”نو د خپل زړۀ خيال ساتئ، او ټګى مۀ کوئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_16.mp3', '', 1761754199, 1761754199),
(50761, 'Malachi 2:17', 'Malachi', 2, 17, 'تاسو مالِک خُدائ په خپلو خبرو ستړے کړو. ”مونږ هغه څنګه ستړے کړو؟“ تاسو تپوس کوئ. په دې وئيلو سره چې، ”ټول بد کوونکى د مالِک خُدائ په نظر کښې ښۀ دى او هغه د هغوئ نه رضا دے،“ يا ”اِنصاف کوونکے خُدائ پاک چرته دے؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi2_verse_17.mp3', '', 1761754199, 1761754199),
(50762, 'Psalms 4:1', 'Psalms', 4, 1, 'ای زما دفاع کوونکی خدایه ته قبوله زما دعا کړه په سختۍ او په تنګۍ کې وکړه تا راسره مرسته مهربان اوسه پر ما او زما واوره دعا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_1.mp3', '', 1761754199, 1761754199),
(50763, 'Psalms 4:2', 'Psalms', 4, 2, 'ترڅو به تاسو سپکوئ ما خلکو؟ ترڅو به تاسو خوښوئ دا بې‌ارزښته شیان؟ ترڅو به ګرځئ په دروغو پسې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_2.mp3', '', 1761754199, 1761754199),
(50764, 'Psalms 4:3', 'Psalms', 4, 3, 'تاسې پوه شئ څښتن کړل غوره وفادار خلک د ځان دپاره کله چې کړمه زه دعا قبلوي یې هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_3.mp3', '', 1761754199, 1761754199),
(50765, 'Psalms 4:4', 'Psalms', 4, 4, 'وېرې نه ولړزېږئ نوره ګناه مه کوئ کله چې تاسو خپل بستر کې غلي پرېوځئ په دې هکله ژور فکر وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_4.mp3', '', 1761754199, 1761754199),
(50766, 'Psalms 4:5', 'Psalms', 4, 5, 'وکړئ مناسبې قربانۍ د خپل څښتن لره او په هغه باندې توکل وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_5.mp3', '', 1761754199, 1761754199),
(50767, 'Psalms 4:6', 'Psalms', 4, 6, 'ډېر خلک پوښتنه کړي او وایي چې «څوک به وي چې وکړي خپل احسان په مونږ؟» ای څښتنه وځلوه نور دې د خپل ځان په مونږ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_6.mp3', '', 1761754199, 1761754199),
(50768, 'Psalms 4:7', 'Psalms', 4, 7, 'تا ماته دومره خوشحالي راکړې چې دي زیاتې د غلو او د شرابو حاصل د هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_7.mp3', '', 1761754199, 1761754199),
(50769, 'Psalms 4:8', 'Psalms', 4, 8, 'څملم او ویده به شم په سوله کې ای څښتنه صرف ته یې چې خوندي به مې ساتې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms4_verse_8.mp3', '', 1761754199, 1761754199),
(50770, 'Psalms 95:1', 'Psalms', 95, 1, 'راځئ چې ووایو څښتن ته د ثنا سندرې! راځئ چې خپل قوي ژغورونکي ته مونږ چیغې د خوښۍ ووهو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_1.mp3', '', 1761754199, 1761754199),
(50771, 'Psalms 95:2', 'Psalms', 95, 2, 'راځئ حضور ته د هغه د شکرانې سره یوځای ورشو وکړو ستاینه په سندرو د خوښۍ د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_2.mp3', '', 1761754199, 1761754199),
(50772, 'Psalms 95:3', 'Psalms', 95, 3, 'ځکه څښتن لوی خدای دی ټولو خدایانو څخه لوی پاچا دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_3.mp3', '', 1761754199, 1761754199),
(50773, 'Psalms 95:4', 'Psalms', 95, 4, 'هغه حکومت کوي په ټولې نړۍ د ځمکې د ژورو برخو څخه د غرو تر لوړو څوکو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_4.mp3', '', 1761754199, 1761754199),
(50774, 'Psalms 95:5', 'Psalms', 95, 5, 'دریابونه د هغه دي ځکه هغه دي پیدا کړي ورکړی ځمکې ته یې شکل دی په خپلو لاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_5.mp3', '', 1761754199, 1761754199),
(50775, 'Psalms 95:6', 'Psalms', 95, 6, 'راځئ چې مونږه په سجده شو عبادت وکړو شو په ګونډو د خپل څښتن او خپل خالق حضور کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_6.mp3', '', 1761754199, 1761754199),
(50776, 'Psalms 95:7', 'Psalms', 95, 7, 'ځکه هغه دی زمونږ خدای مونږه یو قوم د هغه او هغه پام کوي په مونږ باندې لکه شپونکي په شان مونږه یو رمه د هغه چې هغه یې لارښوونه کاندي که تاسو نن واورئ اواز د هغه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_7.mp3', '', 1761754199, 1761754199),
(50777, 'Psalms 95:8', 'Psalms', 95, 8, '«نو مه سختوئ خپل زړونه لکه چې څنګه مو سخت کړي وو په دښته د مسا او مریبه کې تاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_8.mp3', '', 1761754199, 1761754199),
(50778, 'Psalms 95:9', 'Psalms', 95, 9, 'ستاسو نیکونو امتحان کړمه په هغه ځای کې که څه هم دوی ؤ زما عمل لیدلی خو بیا یې هم وازمایلمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_9.mp3', '', 1761754199, 1761754199),
(50779, 'Psalms 95:10', 'Psalms', 95, 10, 'زه له هغه نسل نه څلوېښت کاله بېزاره ومه ما ویل: ‹زما نه لېرې دي د هغوی زړونه نه غواړي عمل وکړي زما په حکمونو باندې›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_10.mp3', '', 1761754199, 1761754199),
(50780, 'Psalms 95:11', 'Psalms', 95, 11, 'نو زه په قهر شوم قسم مې وخوړ: ‹دوی به هېڅکله داخل نه شي هغه هېواد ته چېرته چې زه به ورکومه ارام›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms95_verse_11.mp3', '', 1761754199, 1761754199),
(50781, 'Amos 7:1', 'Amos', 7, 1, 'څښتن تعالی ماته رویا وښودله. په هغې رویا کې ما ولیدل چې وروسته له هغې چې د پټیو څخه هغه حاصلات چې د پاچا برخه وه، راټول شول او د غلو دوهم فصل نوی شین شوی ؤ، څښتن ډلې ډلې ملخان راپیدا کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_1.mp3', '', 1761754199, 1761754199),
(50782, 'Amos 7:2', 'Amos', 7, 2, 'ما په خپلې رویا کې ولیدل چې ملخانو د ځمکې په مخ ټول شنه بوټي وخوړل. نو بیا ما وویل: «ای څښتن تعالی، خپل قوم دې وبخښه! د اسراییلو قوم به څنګه ژوندی پاتې شي؟ هغوی ډېر کوچني او کمزوري دي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_2.mp3', '', 1761754199, 1761754199),
(50783, 'Amos 7:3', 'Amos', 7, 3, 'څښتن د رحم له مخې خپله پرېکړه بدله کړه او ویې ویل: «تا چې څه ولیدل، داسې به نه کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_3.mp3', '', 1761754199, 1761754199),
(50784, 'Amos 7:4', 'Amos', 7, 4, 'څښتن تعالی ماته یوه بله رویا راوښودله. په هغې کې مې ولیدل چې هغه تیاری نیوه چې خپل قوم ته د اور په وسیله سزا ورکړي. هغه اور ژورې بحیرې وسوځولې او د ځمکې په سوځولو یې پیل وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_4.mp3', '', 1761754199, 1761754199),
(50785, 'Amos 7:5', 'Amos', 7, 5, 'بیا ما وویل: «ای څښتن تعالی، بس کړه! د اسراییلو قوم به څنګه ژوندی پاتې شي؟ هغه ډېر کوچنی او کمزوری دی!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_5.mp3', '', 1761754199, 1761754199),
(50786, 'Amos 7:6', 'Amos', 7, 6, 'څښتن خپله پرېکړه بدله کړه او ویې ویل: «تا چې څه ولیدل، هماغسې به نه کیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_6.mp3', '', 1761754199, 1761754199),
(50787, 'Amos 7:7', 'Amos', 7, 7, 'ماته څښتن یوه بله رویا وښودله. په هغې کې ما ولیدل چې څښتن د هغه دېوال په خوا کې چې په شاقول باندې جوړ شوی ؤ، ودرېده او شاقول یې په لاس کې نیولی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_7.mp3', '', 1761754199, 1761754199),
(50788, 'Amos 7:8', 'Amos', 7, 8, 'هغه زما څخه پوښتنه وکړه: «عاموسه، ته څه وینې؟» ما ځواب ورکړ: «زه شاقول وینم.» بیا هغه وویل: «په دې شاقول باندې زه غواړم وښایم چې زما قوم اسراییل د دې دېوال په شان سم نه دی. زه به نور تاسو بې له سزا پرېنږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_8.mp3', '', 1761754199, 1761754199),
(50789, 'Amos 7:9', 'Amos', 7, 9, 'په کومو ځایونو کې چې د اسحاق اولاده عبادت کوي، هغه به وران کړم. د اسراییلو سپېڅلي ځایونه به په کنډوالو باندې بدل شي. زه به د یروبعام پاچا خاندان ختم کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_9.mp3', '', 1761754199, 1761754199),
(50790, 'Amos 7:10', 'Amos', 7, 10, 'د بیت‌ییل کاهن امصیا د اسراییلو پاچا یروبعام ته دا خبر ورولېږه: «عاموس د اسراییلو د خلکو په منځ کې ستا په خلاف دسیسه جوړوي. د هغه خبرې د زغملو وړ نه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_10.mp3', '', 1761754199, 1761754199),
(50791, 'Amos 7:11', 'Amos', 7, 11, 'عاموس داسې وایي: ‹یروبعام به په جنګ کې مړ شي او د اسراییلو خلک به د خپل وطن نه په جلاوطنۍ بوتلل شي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_11.mp3', '', 1761754199, 1761754199),
(50792, 'Amos 7:12', 'Amos', 7, 12, 'بیا امصیا عاموس ته وویل: «ای پیغمبره، نور بس کړه! بېرته یهودا ته لاړ شه او هلته خپله پېشګویي کوه. هغوی به درته د دې دپاره پیسې درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_12.mp3', '', 1761754199, 1761754199),
(50793, 'Amos 7:13', 'Amos', 7, 13, 'په بیت‌ییل کې نورې پېشګویانې مه کوه. دا د پاچا د عبادت ځای دی او د ټولو خلکو عبادتځای دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_13.mp3', '', 1761754199, 1761754199),
(50794, 'Amos 7:14', 'Amos', 7, 14, 'عاموس په ځواب کې وویل: «زه پیغمبر نه یم او نه زما پلار پیغمبر ؤ. زه یوازې شپون یم او د انځرو ونې ساتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_14.mp3', '', 1761754199, 1761754199),
(50795, 'Amos 7:15', 'Amos', 7, 15, 'خو څښتن زما نه شپونتوب واخیست او حکم یې راته وکړ: ‹لاړ شه او زما قوم اسراییلو ته پېشګویي وکړه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_15.mp3', '', 1761754199, 1761754199),
(50796, 'Amos 7:16', 'Amos', 7, 16, 'نو اوس د څښتن خبرو ته غوږ ونیسه. ته ماته وایې چې پېشګویانې بس کړم او د اسراییلو د قوم په خلاف وعظ کول پرېږدم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_16.mp3', '', 1761754199, 1761754199),
(50797, 'Amos 7:17', 'Amos', 7, 17, 'نو ای امصیا، څښتن تاته داسې وایي: ‹ستا د ښځې نه به د ښار فاحشه جوړه شي او زامن او لورګانې به دې په جنګ کې مړه شي. ستا وطن به په شاقول باندې اندازه او ووېشل شي او نورو ته به ورکړل شي او ته په خپله به په یو کافر وطن کې مړ شې او اسراییل به خامخا د خپل وطن څخه په جلاوطنۍ بوتلل شي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos7_verse_17.mp3', '', 1761754199, 1761754199),
(50798, 'Psalms 115:1', 'Psalms', 115, 1, 'مونږ ته نه ای څښتنه مونږ ته نه بلکې خپل نوم ته جلال ورکړه! د خپلې مینې او وفا په سبب', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_1.mp3', '', 1761754199, 1761754199),
(50799, 'Psalms 115:2', 'Psalms', 115, 2, 'ولې قومونه دا پوښتنه وکړي چې د دوی خدای چېرته دی؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_2.mp3', '', 1761754199, 1761754199),
(50800, 'Psalms 115:3', 'Psalms', 115, 3, 'زمونږ خدای دی په اسمان کې هغه کوي هغه څه چې څه یې خوښه وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_3.mp3', '', 1761754199, 1761754199),
(50801, 'Psalms 115:4', 'Psalms', 115, 4, 'د سرو او سپینو زرو جوړ دي د هغوی بتان هغه جوړ شوي د انسان په لاسو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_4.mp3', '', 1761754199, 1761754199),
(50802, 'Psalms 115:5', 'Psalms', 115, 5, 'د هغوی خولې شته، خو خبرې پرې کولای نه شي سترګې یې شته، خو پرې لیدلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_5.mp3', '', 1761754199, 1761754199),
(50803, 'Psalms 115:6', 'Psalms', 115, 6, 'غوږونه یې شته، خو پرې اورېدلی نه شي پوزې یې شته، خو څه بوی کولای نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_6.mp3', '', 1761754199, 1761754199),
(50804, 'Psalms 115:7', 'Psalms', 115, 7, 'لاسونه یې شته، خو څه لمس کولای نه شي پښې یې شته، خو ګرځېدلی نه شي د هغوی د ستوني نه اواز نه وځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_7.mp3', '', 1761754199, 1761754199),
(50805, 'Psalms 115:8', 'Psalms', 115, 8, 'چې جوړوي څوک هغه او څوک چې باور پرې لري هغوی دې شي هغو بتانو په شان چې جوړوي هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_8.mp3', '', 1761754199, 1761754199),
(50806, 'Psalms 115:9', 'Psalms', 115, 9, 'ای اسراییلو، په څښتن باندې توکل کوئ دی مرستندوی ستاسو او ستاسو سپر دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_9.mp3', '', 1761754199, 1761754199),
(50807, 'Psalms 115:10', 'Psalms', 115, 10, 'ای کاهنانو ای د هارون اولادې توکل وکړئ په څښتن باندې دی مرستندوی ستاسو او ستاسو سپر دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_10.mp3', '', 1761754199, 1761754199),
(50808, 'Psalms 115:11', 'Psalms', 115, 11, 'توکل وکړئ په څښتن باندې ای تاسو ټول چې ترې وېره کوئ دی مرستندوی ستاسو او ستاسو سپر دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_11.mp3', '', 1761754199, 1761754199),
(50809, 'Psalms 115:12', 'Psalms', 115, 12, 'رایادوي مونږ څښتن او برکت به راکړي هغه به ورکړي برکت اسراییلیانو ته او د هارون اولادې یعنې کاهنانو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_12.mp3', '', 1761754199, 1761754199),
(50810, 'Psalms 115:13', 'Psalms', 115, 13, 'هغه به ورکړي برکت هغو ته چې کړي وېره له څښتنه څخه لویو او وړو ته یوشان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms115_verse_13.mp3', '', 1761754199, 1761754199);